import{z as o,x as i,o as l,c as p,q as t,j as B,D as e,d as a,s,S as n,b as A}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"多轮 RL 的环境工程","description":"","frontmatter":{"title":"多轮 RL 的环境工程","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rlsys-multiturn-env.md","filePath":"llm/rlsys-multiturn-env.md","lastUpdated":1791413859000}'),d={name:"llm/rlsys-multiturn-env.md"};function m(D,E,C,F,h,u){const r=i("Mermaid");return l(),p("div",null,[E[2]||(E[2]=t('<h1 id="多轮-rl-的环境工程" tabindex="-1">多轮 RL 的环境工程 <a class="header-anchor" href="#多轮-rl-的环境工程" aria-label="Permalink to &quot;多轮 RL 的环境工程&quot;">​</a></h1><div class="epigraph"><p>单轮 RL 的环境是提示词；多轮的环境是一个有状态、会超时、偶尔崩溃的进程——工程量从采样器挪到了环境侧。</p><footer>—— 据 Nakano 等 WebGPT 2021 与工具整合、代码 RL 环境的公开工程实践整理</footer></div><p><a href="/llm/rlsys-inference-in-loop">上一课</a>把推理引擎接进循环，生成端能稳定吐单轮经验。本课把「一问一答」升级成「多轮交互」：模型要调工具、读观测、再决策，环境从静态提示变成有状态的服务。推理 RL 的前沿（工具整合、代码修复、网页操作）都长在这层工程上，<a href="/llm/reasoning-rl-loop">推理 RL 闭环</a>里它是产能瓶颈。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多轮把三件事复杂化了。轨迹结构：一次经验是「助手—工具—观测」交替的长序列，哪些 token 进损失？工具返回与系统注入的文本不是模型的行为，算进策略梯度等于教模型模仿工具输出。信用分配：奖励只在轨迹末端（测试通过、任务完成），中间回合没有直接信号，轨迹越长自方差越大。环境吞吐：沙箱里跑测试要秒到分钟级且彼此不均，最慢的环境决定批次完成时间，训练器永远在等最慢的样本。</p><p><span class="marginnote">直觉类比：环境池像并排水龙头往同一个桶里注水，批次完成时间取决于最慢那根管子。九个环境 5 秒完成、一个要 90 秒，GPU 照样空等 85 秒——所以沙箱限额（墙钟、内存上限）不是防滥用的小配置，而是保吞吐的生命线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>环境抽象成 reset/step 接口：step 的动作是助手回合，返回观测、是否终止、可选的中间奖励。</p><p><span class="marginnote">「reset/step」是从游戏借来的老接口：reset 开一局新任务，step 把模型的一个动作（这里是整个助手回合）交给环境，换回观测和「完没完」。相当于给沙箱装一个标准插座——不管里面跑的是终端、浏览器还是测试套件，训练器只认这两个按钮。</span></p><p>四条工程决定。掩码：损失只在助手生成的 token 上计算，工具输出与观测全部 mask 掉，mask 列作为经验的一列随样本走。工具调用走结构化通道：函数名与参数的协议要可解析，解析失败的调用按环境规则计分或截断（<a href="/llm/tool-integrated-rl">工具整合推理 RL</a>）。沙箱限额：每个环境实例有墙钟、内存与网络上限，超时返回错误观测让模型学会绕开，而不是挂死整批。断点续跑：环境状态可序列化，轨迹可以暂停（等工具、等新权重）再续，跨版本拼接必须带版本标记（<a href="/llm/async-rollout-arch">异步 rollout 架构</a>的 partial rollout 在环境层的落点）。</p><p><span class="marginnote">数字实例看掩码省了什么：一条 10 轮轨迹共 8000 token，助手自己写的只有 3000，工具输出与观测占 5000。掩码就是给这 5000 个位置记零——不进损失、不算优势，但照常进上下文供注意力读取。若无掩码，梯度会按着头教模型「背诵」工具的输出。</span></p><p><span class="marginnote">代码 RL 环境的两条硬账：测试套件的墙钟上限决定批次节奏，几分钟的测试会把你压到一天几步；失败测试的报错全文直接进上下文，几个回合就能把窗口吃满——观测要截成摘要，预算写进配置（见<a href="/llm/length-budget-rl">长度预算与截断</a>）。</span></p>',12)),(l(),B(n,null,{default:e(()=>[s(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%BB%BB%E5%8A%A1%EF%BC%9Areset%22%5D%20--%3E%20A1%5B%22%E5%8A%A9%E6%89%8B%E5%9B%9E%E5%90%88%201%EF%BC%9A%E8%BF%9B%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20A1%20--%3E%20TOOL%5B%22%E5%B7%A5%E5%85%B7%E8%B0%83%E7%94%A8%20%E2%86%92%20%E6%B2%99%E7%AE%B1%E6%89%A7%E8%A1%8C%EF%BC%88%E5%A2%99%E9%92%9F%2F%E5%86%85%E5%AD%98%E9%99%90%E9%A2%9D%EF%BC%89%22%5D%0A%20%20TOOL%20--%3E%20OBS%5B%22%E8%A7%82%E6%B5%8B%E4%B8%8E%E6%8A%A5%E9%94%99%E6%91%98%E8%A6%81%EF%BC%9Amask%EF%BC%8C%E4%B8%8D%E8%BF%9B%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20OBS%20--%3E%20A2%5B%22%E5%8A%A9%E6%89%8B%E5%9B%9E%E5%90%88%202%EF%BC%9A%E8%BF%9B%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20A2%20--%3E%20END%7B%22%E7%BB%88%E6%AD%A2%EF%BC%9F%22%7D%0A%20%20END%20--%3E%7C%E5%90%A6%7C%20TOOL%0A%20%20END%20--%3E%7C%E6%98%AF%7C%20R%5B%22%E8%BD%A8%E8%BF%B9%E6%9C%AB%E5%A5%96%E5%8A%B1%20%E2%86%92%20%E6%8C%89%E6%8E%A9%E7%A0%81%E7%AE%97%E4%BC%98%E5%8A%BF%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("掩码与奖励放置共同定义了「策略认为自己控制什么」。梯度只在掩码内流动，所以 mask 是因果边界的声明：工具与观测属于环境，如同 MDP 的转移函数，不该被优化。奖励挂在最后一个助手 token（或按 "),A("a",{href:"/llm/token-level-reward"},"token 级奖励塑形"),a("摊到助手 token），优势以轨迹为单位估计。环境有状态之后，「同分布采样」也要重审：reset 的任务分布就是环境的 MDP 定义，任务难度与分布偏置直接成为策略梯度估计的偏置来源——环境设计就是奖励设计，这句话在多轮里才显出全部分量。")],-1)),(l(),B(n,null,{default:e(()=>[s(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20R%5B%22reset%EF%BC%9A%E4%BB%BB%E5%8A%A1%E5%88%86%E5%B8%83%20%3D%20%E7%8E%AF%E5%A2%83%E7%9A%84%20MDP%20%E5%AE%9A%E4%B9%89%22%5D%20--%3E%20M%5B%22%E9%9A%BE%E5%BA%A6%E6%B7%B7%E5%90%88%EF%BC%9A%E7%AE%80%E5%8D%95%20%2F%20%E4%B8%AD%E7%AD%89%20%2F%20%E5%A4%AA%E9%9A%BE%22%5D%0A%20%20M%20--%3E%7C%22%E5%A4%AA%E7%AE%80%E5%8D%95%EF%BC%9A%E5%85%A8%E5%AF%B9%22%7C%20Z%5B%22%E9%9B%B6%E6%96%B9%E5%B7%AE%E7%BB%84%EF%BC%9A%E6%97%A0%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20M%20--%3E%7C%22%E5%A4%AA%E9%9A%BE%EF%BC%9A%E5%85%A8%E9%94%99%22%7C%20Z%0A%20%20M%20--%3E%7C%22%E4%B8%AD%E7%AD%89%EF%BC%9A%E6%9C%89%E5%AF%B9%E6%9C%89%E9%94%99%22%7C%20G%5B%22%E6%9C%89%E6%95%88%E7%BB%84%EF%BC%9A%E6%9C%89%E6%A2%AF%E5%BA%A6%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20R%20--%3E%7C%22%E9%9A%BE%E5%BA%A6%E9%85%8D%E6%AF%94%E5%8D%B3%E5%81%8F%E7%BD%AE%22%7C%20B%5B%22%E7%AD%96%E7%95%A5%E6%A2%AF%E5%BA%A6%E7%9A%84%E5%81%8F%E7%BD%AE%E6%9D%A5%E6%BA%90%22%5D%0A%20%20G%20--%3E%20O%5B%22%E4%BC%98%E5%8C%96%E6%96%B9%E5%90%91%E9%9A%8F%E4%BB%BB%E5%8A%A1%E9%85%8D%E6%AF%94%E5%8F%98%E5%8C%96%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>环境工程不解决信用分配：末端奖励下的长轨迹方差仍靠组基线与优势估计压制，中间奖励是可选的塑形而非免费午餐（塑形有偏）。沙箱既是安全边界也是测量边界：模型可能学会「让测试变绿」而不是「让代码正确」——<a href="/llm/reward-hacking-llm">奖励黑客</a>的环境版。环境池的可用性是新单点，其吞吐上限直接给出训练吞吐上限；代码修复类环境（<a href="/llm/swe-rl-env">代码 RL 与 SWE 环境</a>）把这笔账推到极限。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>环境抽象为 reset/step；任务分布即 MDP 定义，环境设计就是奖励设计。</li><li>loss mask 只保留助手 token：工具与观测是环境，不是行为。</li><li>沙箱限额（墙钟、内存、网络）防挂死；观测进上下文前截成摘要并计入预算。</li><li>轨迹可暂停续跑，跨版本拼接必须带版本标记；环境池吞吐是训练吞吐的上界。</li><li>出处：Nakano 等，WebGPT，2021；据工具整合与 SWE 环境的公开工程实践整理。</li></ul>',4))])}const k=o(d,[["render",m]]);export{c as __pageData,k as default};
